import AppKit

/// The Codex app logo (blue cloud with terminal prompt), cropped from the
/// official app icon and embedded as base64 — avoids SPM resource-bundle
/// packaging so make_app.sh can keep shipping a bare binary.
enum CodexLogo {
    private static let pngBase64 = """

"""
    /// Full-color at menu bar size; not a template (the mark is inherently colored).
    static var image: NSImage? {
        guard let data = Data(base64Encoded: pngBase64, options: .ignoreUnknownCharacters),
              let image = NSImage(data: data) else { return nil }
        image.size = NSSize(width: 13, height: 13)
        return image
    }
}
